import { relations, sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  serial,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { user } from "./auth-schema";

// Better Auth tables (generated by `npx auth generate`; do not hand-edit).
export * from "./auth-schema";

const createdAt = () => timestamp({ withTimezone: true }).defaultNow().notNull();
const updatedAt = () =>
  timestamp({ withTimezone: true })
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull();

/* ───────────────────────── Customers ───────────────────────── */

/** Store-specific customer data kept out of the Better Auth `user` table. */
export const profile = pgTable("profile", {
  userId: text()
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  phone: text(),
  marketingOptIn: boolean().notNull().default(false),
  updatedAt: updatedAt(),
});

export const address = pgTable(
  "address",
  {
    id: serial().primaryKey(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    label: text().notNull(),
    line1: text().notNull(),
    area: text().notNull(),
    zoneId: integer().references(() => shippingZone.id, { onDelete: "set null" }),
    phone: text().notNull(),
    isDefault: boolean().notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index("address_user_idx").on(t.userId)],
);

/* ───────────────────────── Catalogue ───────────────────────── */

export const category = pgTable("category", {
  id: serial().primaryKey(),
  slug: text().notNull().unique(),
  name: text().notNull(),
  description: text().notNull().default(""),
  sort: integer().notNull().default(0),
  createdAt: createdAt(),
});

export const occasion = pgTable("occasion", {
  id: serial().primaryKey(),
  slug: text().notNull().unique(),
  name: text().notNull(),
  blurb: text().notNull().default(""),
  imageUrl: text(),
  sort: integer().notNull().default(0),
});

export const product = pgTable(
  "product",
  {
    id: serial().primaryKey(),
    slug: text().notNull().unique(),
    name: text().notNull(),
    shortDescription: text().notNull().default(""),
    description: text().notNull().default(""),
    categoryId: integer().references(() => category.id, { onDelete: "set null" }),
    status: text().notNull().default("draft"),
    featured: boolean().notNull().default(false),
    spiceLevel: integer().notNull().default(1),
    reorderDays: integer().notNull().default(7),
    isSide: boolean().notNull().default(false),
    seoTitle: text(),
    seoDescription: text(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check("product_status_chk", sql`${t.status} in ('draft','active','archived')`),
    check("product_spice_chk", sql`${t.spiceLevel} between 0 and 3`),
    check("product_reorder_chk", sql`${t.reorderDays} between 1 and 90`),
    index("product_category_idx").on(t.categoryId),
  ],
);

export const productVariant = pgTable(
  "product_variant",
  {
    id: serial().primaryKey(),
    productId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    name: text().notNull(),
    sku: text().notNull().unique(),
    priceKobo: integer().notNull(),
    compareAtKobo: integer(),
    stock: integer().notNull().default(0),
    sort: integer().notNull().default(0),
    active: boolean().notNull().default(true),
  },
  (t) => [
    check("variant_price_chk", sql`${t.priceKobo} > 0`),
    check("variant_compare_chk", sql`${t.compareAtKobo} is null or ${t.compareAtKobo} > ${t.priceKobo}`),
    check("variant_stock_chk", sql`${t.stock} >= 0`),
    index("variant_product_idx").on(t.productId),
  ],
);

export const productImage = pgTable(
  "product_image",
  {
    id: serial().primaryKey(),
    productId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    url: text().notNull(),
    alt: text().notNull().default(""),
    sort: integer().notNull().default(0),
  },
  (t) => [index("image_product_idx").on(t.productId)],
);

export const productOccasion = pgTable(
  "product_occasion",
  {
    productId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    occasionId: integer()
      .notNull()
      .references(() => occasion.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.productId, t.occasionId] })],
);

/** "Complete your meal" side suggestions. */
export const productSide = pgTable(
  "product_side",
  {
    productId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    sideProductId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.productId, t.sideProductId] })],
);

export const combo = pgTable("combo", {
  id: serial().primaryKey(),
  slug: text().notNull().unique(),
  name: text().notNull(),
  description: text().notNull().default(""),
  imageUrl: text(),
  /** Combo price; must be below the sum of its items (savings shown). */
  priceKobo: integer().notNull(),
  active: boolean().notNull().default(true),
  sort: integer().notNull().default(0),
  createdAt: createdAt(),
}, (t) => [check("combo_price_chk", sql`${t.priceKobo} > 0`)]);

export const comboItem = pgTable(
  "combo_item",
  {
    id: serial().primaryKey(),
    comboId: integer()
      .notNull()
      .references(() => combo.id, { onDelete: "cascade" }),
    variantId: integer()
      .notNull()
      .references(() => productVariant.id, { onDelete: "restrict" }),
    qty: integer().notNull().default(1),
  },
  (t) => [
    check("combo_item_qty_chk", sql`${t.qty} between 1 and 20`),
    uniqueIndex("combo_item_uniq").on(t.comboId, t.variantId),
  ],
);

/* ───────────────────────── Delivery ───────────────────────── */

export const shippingZone = pgTable(
  "shipping_zone",
  {
    id: serial().primaryKey(),
    name: text().notNull(),
    areas: text().notNull().default(""),
    feeKobo: integer().notNull(),
    freeOverKobo: integer(),
    etaText: text().notNull().default(""),
    active: boolean().notNull().default(true),
    sort: integer().notNull().default(0),
  },
  (t) => [check("zone_fee_chk", sql`${t.feeKobo} >= 0`)],
);

/* ───────────────────────── Cart ───────────────────────── */

export const cart = pgTable(
  "cart",
  {
    /** Random token, also stored in the httpOnly cart cookie. */
    id: text().primaryKey(),
    userId: text().references(() => user.id, { onDelete: "set null" }),
    email: text(),
    lastActiveAt: timestamp({ withTimezone: true }).defaultNow().notNull(),
    remindersSent: integer().notNull().default(0),
    lastReminderAt: timestamp({ withTimezone: true }),
    convertedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    check("cart_reminders_chk", sql`${t.remindersSent} between 0 and 2`),
    index("cart_user_idx").on(t.userId),
  ],
);

export const cartItem = pgTable(
  "cart_item",
  {
    id: serial().primaryKey(),
    cartId: text()
      .notNull()
      .references(() => cart.id, { onDelete: "cascade" }),
    variantId: integer().references(() => productVariant.id, { onDelete: "cascade" }),
    comboId: integer().references(() => combo.id, { onDelete: "cascade" }),
    qty: integer().notNull(),
  },
  (t) => [
    check("cart_item_qty_chk", sql`${t.qty} between 1 and 20`),
    check("cart_item_one_chk", sql`(${t.variantId} is null) <> (${t.comboId} is null)`),
    uniqueIndex("cart_item_variant_uniq").on(t.cartId, t.variantId),
    uniqueIndex("cart_item_combo_uniq").on(t.cartId, t.comboId),
  ],
);

/* ───────────────────────── Orders ───────────────────────── */

export const coupon = pgTable(
  "coupon",
  {
    id: serial().primaryKey(),
    code: text().notNull().unique(),
    kind: text().notNull(),
    /** percent: 1–100; fixed: kobo */
    value: integer().notNull(),
    minSubtotalKobo: integer().notNull().default(0),
    startsAt: timestamp({ withTimezone: true }),
    endsAt: timestamp({ withTimezone: true }),
    maxUses: integer(),
    usedCount: integer().notNull().default(0),
    /** welcome | referral | influencer | manual | personal */
    source: text().notNull().default("manual"),
    influencer: text(),
    /** Personal codes can only be used by this email. */
    ownerEmail: text(),
    active: boolean().notNull().default(true),
    createdAt: createdAt(),
  },
  (t) => [
    check("coupon_kind_chk", sql`${t.kind} in ('percent','fixed')`),
    check(
      "coupon_value_chk",
      sql`(${t.kind} = 'percent' and ${t.value} between 1 and 100) or (${t.kind} = 'fixed' and ${t.value} > 0)`,
    ),
    check("coupon_used_chk", sql`${t.usedCount} >= 0`),
  ],
);

export const order = pgTable(
  "order",
  {
    id: serial().primaryKey(),
    number: text().notNull().unique(),
    userId: text().references(() => user.id, { onDelete: "set null" }),
    email: text().notNull(),
    phone: text().notNull(),
    name: text().notNull(),
    /** delivery | pickup */
    method: text().notNull(),
    addressLine: text(),
    area: text(),
    zoneId: integer().references(() => shippingZone.id, { onDelete: "set null" }),
    zoneName: text(),
    notes: text(),
    status: text().notNull().default("pending_payment"),
    subtotalKobo: integer().notNull(),
    discountKobo: integer().notNull().default(0),
    deliveryKobo: integer().notNull().default(0),
    totalKobo: integer().notNull(),
    currency: text().notNull().default("NGN"),
    couponId: integer().references(() => coupon.id, { onDelete: "set null" }),
    couponCode: text(),
    referralCode: text(),
    paymentExpiresAt: timestamp({ withTimezone: true }).notNull(),
    paidAt: timestamp({ withTimezone: true }),
    /** Rider name / phone for delivery. */
    tracking: text(),
    statusChangedAt: timestamp({ withTimezone: true }).defaultNow().notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check("order_method_chk", sql`${t.method} in ('delivery','pickup')`),
    check(
      "order_status_chk",
      sql`${t.status} in ('pending_payment','confirmed','preparing','out_for_delivery','delivered','cancelled','expired','refunded')`,
    ),
    check(
      "order_money_chk",
      sql`${t.subtotalKobo} >= 0 and ${t.discountKobo} >= 0 and ${t.deliveryKobo} >= 0 and ${t.totalKobo} >= 0`,
    ),
    index("order_user_idx").on(t.userId),
    index("order_email_idx").on(t.email),
    index("order_status_idx").on(t.status),
    index("order_created_idx").on(t.createdAt),
  ],
);

export const orderItem = pgTable(
  "order_item",
  {
    id: serial().primaryKey(),
    orderId: integer()
      .notNull()
      .references(() => order.id, { onDelete: "cascade" }),
    productId: integer().references(() => product.id, { onDelete: "set null" }),
    variantId: integer().references(() => productVariant.id, { onDelete: "set null" }),
    comboId: integer().references(() => combo.id, { onDelete: "set null" }),
    name: text().notNull(),
    size: text().notNull().default(""),
    imageUrl: text(),
    unitKobo: integer().notNull(),
    qty: integer().notNull(),
  },
  (t) => [
    check("order_item_qty_chk", sql`${t.qty} between 1 and 50`),
    check("order_item_unit_chk", sql`${t.unitKobo} >= 0`),
    index("order_item_order_idx").on(t.orderId),
  ],
);

/** Stock reserved per variant for an order (combos expand into variants). */
export const orderReservation = pgTable(
  "order_reservation",
  {
    orderId: integer()
      .notNull()
      .references(() => order.id, { onDelete: "cascade" }),
    variantId: integer()
      .notNull()
      .references(() => productVariant.id, { onDelete: "cascade" }),
    qty: integer().notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.orderId, t.variantId] }),
    check("reservation_qty_chk", sql`${t.qty} > 0`),
  ],
);

export const orderEvent = pgTable(
  "order_event",
  {
    id: serial().primaryKey(),
    orderId: integer()
      .notNull()
      .references(() => order.id, { onDelete: "cascade" }),
    type: text().notNull(),
    fromStatus: text(),
    toStatus: text(),
    note: text(),
    actor: text().notNull().default("system"),
    createdAt: createdAt(),
  },
  (t) => [index("order_event_order_idx").on(t.orderId)],
);

export const payment = pgTable(
  "payment",
  {
    id: serial().primaryKey(),
    orderId: integer()
      .notNull()
      .references(() => order.id, { onDelete: "cascade" }),
    provider: text().notNull().default("paystack"),
    reference: text().notNull().unique(),
    amountKobo: integer().notNull(),
    currency: text().notNull().default("NGN"),
    /** pending | success | failed | abandoned */
    status: text().notNull().default("pending"),
    channel: text(),
    paidAmountKobo: integer(),
    flagged: text(),
    raw: jsonb(),
    createdAt: createdAt(),
    verifiedAt: timestamp({ withTimezone: true }),
  },
  (t) => [index("payment_order_idx").on(t.orderId)],
);

export const couponRedemption = pgTable(
  "coupon_redemption",
  {
    id: serial().primaryKey(),
    couponId: integer()
      .notNull()
      .references(() => coupon.id, { onDelete: "cascade" }),
    email: text().notNull(),
    orderId: integer()
      .notNull()
      .references(() => order.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("redemption_once_per_email").on(t.couponId, t.email)],
);

/* ───────────────────────── Growth ───────────────────────── */

export const referralCode = pgTable("referral_code", {
  userId: text()
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  code: text().notNull().unique(),
  createdAt: createdAt(),
});

export const referralReward = pgTable(
  "referral_reward",
  {
    id: serial().primaryKey(),
    referrerUserId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    refereeEmail: text().notNull(),
    orderId: integer().references(() => order.id, { onDelete: "set null" }),
    rewardCouponId: integer().references(() => coupon.id, { onDelete: "set null" }),
    createdAt: createdAt(),
  },
  // A friend can only ever trigger one referral reward.
  (t) => [uniqueIndex("referral_referee_uniq").on(t.refereeEmail)],
);

export const review = pgTable(
  "review",
  {
    id: serial().primaryKey(),
    productId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    userId: text().references(() => user.id, { onDelete: "set null" }),
    orderId: integer().references(() => order.id, { onDelete: "set null" }),
    authorName: text().notNull(),
    rating: integer().notNull(),
    /** mild | hot | extra_hot */
    spiceLevel: text().notNull(),
    title: text().notNull().default(""),
    body: text().notNull(),
    status: text().notNull().default("pending"),
    createdAt: createdAt(),
  },
  (t) => [
    check("review_rating_chk", sql`${t.rating} between 1 and 5`),
    check("review_status_chk", sql`${t.status} in ('pending','approved','rejected')`),
    check("review_spice_chk", sql`${t.spiceLevel} in ('mild','hot','extra_hot')`),
    uniqueIndex("review_user_product_uniq").on(t.userId, t.productId),
    index("review_product_idx").on(t.productId),
  ],
);

export const favourite = pgTable(
  "favourite",
  {
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    productId: integer()
      .notNull()
      .references(() => product.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.productId] })],
);

export const subscriber = pgTable("subscriber", {
  id: serial().primaryKey(),
  email: text().notNull().unique(),
  source: text().notNull().default("newsletter"),
  createdAt: createdAt(),
});

export const stockAlert = pgTable(
  "stock_alert",
  {
    id: serial().primaryKey(),
    email: text().notNull(),
    variantId: integer()
      .notNull()
      .references(() => productVariant.id, { onDelete: "cascade" }),
    notifiedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("stock_alert_uniq").on(t.email, t.variantId)],
);

export const quizResult = pgTable(
  "quiz_result",
  {
    id: serial().primaryKey(),
    userId: text().references(() => user.id, { onDelete: "cascade" }),
    email: text(),
    answers: jsonb().notNull(),
    productIds: jsonb().$type<number[]>().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("quiz_user_idx").on(t.userId)],
);

export const pushSubscription = pgTable("push_subscription", {
  id: serial().primaryKey(),
  userId: text()
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  endpoint: text().notNull().unique(),
  p256dh: text().notNull(),
  auth: text().notNull(),
  userAgent: text(),
  createdAt: createdAt(),
});

/**
 * Customer phone alerts for ONE order (works for guests too). Removed when the order finishes.
 * The same device can follow several orders, so endpoint is unique per order, not globally.
 */
export const orderPush = pgTable(
  "order_push",
  {
    id: serial().primaryKey(),
    orderId: integer()
      .notNull()
      .references(() => order.id, { onDelete: "cascade" }),
    endpoint: text().notNull(),
    p256dh: text().notNull(),
    auth: text().notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("order_push_order_endpoint_uniq").on(t.orderId, t.endpoint)],
);

/** Craving / reorder reminders already sent (one per order item product). */
export const reminderLog = pgTable(
  "reminder_log",
  {
    id: serial().primaryKey(),
    kind: text().notNull(),
    key: text().notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("reminder_log_uniq").on(t.kind, t.key)],
);

/* ───────────────────────── Settings & limits ───────────────────────── */

/** Single-row store settings editable by the admin (cached by tag). */
export const storeSettings = pgTable(
  "store_settings",
  {
    id: integer().primaryKey().default(1),
    whatsappNumber: text(),
    bannerDesktop: text(),
    bannerMobile: text(),
    updatedAt: timestamp({ withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [check("store_settings_singleton", sql`${t.id} = 1`)],
);

/** App-level DB-backed rate limits (cart, checkout, lookup, reviews, uploads...). */
export const throttle = pgTable("throttle", {
  key: text().primaryKey(),
  count: integer().notNull().default(0),
  windowStart: timestamp({ withTimezone: true }).defaultNow().notNull(),
});

/* ───────────────────────── Relations ───────────────────────── */

export const productRelations = relations(product, ({ one, many }) => ({
  category: one(category, { fields: [product.categoryId], references: [category.id] }),
  variants: many(productVariant),
  images: many(productImage),
  occasions: many(productOccasion),
  reviews: many(review),
}));

export const variantRelations = relations(productVariant, ({ one }) => ({
  product: one(product, { fields: [productVariant.productId], references: [product.id] }),
}));

export const imageRelations = relations(productImage, ({ one }) => ({
  product: one(product, { fields: [productImage.productId], references: [product.id] }),
}));

export const productOccasionRelations = relations(productOccasion, ({ one }) => ({
  product: one(product, { fields: [productOccasion.productId], references: [product.id] }),
  occasion: one(occasion, { fields: [productOccasion.occasionId], references: [occasion.id] }),
}));

export const comboRelations = relations(combo, ({ many }) => ({
  items: many(comboItem),
}));

export const comboItemRelations = relations(comboItem, ({ one }) => ({
  combo: one(combo, { fields: [comboItem.comboId], references: [combo.id] }),
  variant: one(productVariant, { fields: [comboItem.variantId], references: [productVariant.id] }),
}));

export const orderRelations = relations(order, ({ many }) => ({
  items: many(orderItem),
  events: many(orderEvent),
  payments: many(payment),
}));

export const orderItemRelations = relations(orderItem, ({ one }) => ({
  order: one(order, { fields: [orderItem.orderId], references: [order.id] }),
}));

export const orderEventRelations = relations(orderEvent, ({ one }) => ({
  order: one(order, { fields: [orderEvent.orderId], references: [order.id] }),
}));

export const paymentRelations = relations(payment, ({ one }) => ({
  order: one(order, { fields: [payment.orderId], references: [order.id] }),
}));

export const reviewRelations = relations(review, ({ one }) => ({
  product: one(product, { fields: [review.productId], references: [product.id] }),
}));

export const cartRelations = relations(cart, ({ many }) => ({
  items: many(cartItem),
}));

export const cartItemRelations = relations(cartItem, ({ one }) => ({
  cart: one(cart, { fields: [cartItem.cartId], references: [cart.id] }),
  variant: one(productVariant, { fields: [cartItem.variantId], references: [productVariant.id] }),
  combo: one(combo, { fields: [cartItem.comboId], references: [combo.id] }),
}));
